      display: inline-flex;
      align-items: center;
      gap: .3rem;
      margin: .15rem .2rem .15rem 0;
      padding: .14rem .45rem;
      border: 1px solid rgba(91, 197, 255, .28);
      border-radius: 999px;
      color: var(--wa-blue-soft);
      background: rgba(91, 197, 255, .06);
      font-size: .78rem;
